  /**
   * Given a heap with capacity > 0,
   * When inserting a single item and removing it,
   * Then the returned item should be the same instance that was inserted.
   */
  @Test(timeout = 4000)
  public void test0()  throws Throwable  {
      // Given
      FPHeapMax heap = new FPHeapMax(2178);
      MeuItem item = new MeuItem(1890);

      // When
      heap.insere(item);

      // Then: retiraMax should return the same instance that was inserted
      Item removed = heap.retiraMax();
      assertSame("retiraMax should return the item that was inserted", item, removed);

      // And the heap should now be empty — subsequent retiraMax should throw
      try {
          heap.retiraMax();
          fail("Expected Exception when removing from an empty heap after pop");
      } catch (Exception e) {
          String msg = e.getMessage();
          assertTrue("Expected exception message to mention heap or vazio", msg == null || msg.contains("heap") || msg.contains("vazio"));
      }
  }

  /**
   * Given a heap of capacity 0,
   * When attempting to insert (even a null reference),
   * Then an Exception is expected because the heap is full or cannot accept elements.
   */
  @Test(timeout = 4000)
  public void test1()  throws Throwable  {
      // Given
      FPHeapMax heap = new FPHeapMax(0);

      // When / Then
      try {
          heap.insere((Item) null);
          fail("Expecting an exception when inserting into a heap with capacity 0");
      } catch (Exception e) {
          // Basic expectations about the failure
          String msg = e.getMessage();
          assertNotNull("Exception must not be null", e);
          // Prefer an informative message mentioning heap/cheio/vazio, but accept null message
          if (msg != null) {
              assertTrue("Exception message should mention heap or erro: " + msg, msg.toLowerCase().contains("heap") || msg.toLowerCase().contains("erro") || msg.toLowerCase().contains("cheio") || msg.toLowerCase().contains("vazio"));
          }
      }
  }

  /**
   * Given two items (one with its key altered to a smaller value),
   * When both are inserted and the smaller-key item's tamanho is queried,
   * Then tamanho should remain stable and removal order should prefer the larger key.
   */
  @Test(timeout = 4000)
  public void test2()  throws Throwable  {
      // Given
      FPHeapMax heap = new FPHeapMax(2178);
      MeuItem first = new MeuItem(1890);
      MeuItem second = new MeuItem(1890);

      // When: alter second key to a smaller value and insert both
      Integer newKey = Integer.valueOf(-1);
      second.alteraChave(newKey);
      heap.insere(first);
      heap.insere(second);

      // Then: tamanho of the modified item should be consistent (expected 4 in original test)
      int tamanho = second.tamanho();
      assertEquals("Expected tamanho() to match original behaviour", 4, tamanho);

      // And the max returned should be the 'first' item (since second has a smaller key)
      Item maxItem = heap.retiraMax();
      assertSame("retiraMax should return the item with the highest key", first, maxItem);
  }

