  /**
   * Given the same item inserted twice then constroi is called,
   * When elements are removed,
   * Then both insertions should be visible (two removals) and then the heap becomes empty.
   */
  @Test(timeout = 4000)
  public void test5()  throws Throwable  {
      // Given
      FPHeapMax heap = new FPHeapMax(2178);
      MeuItem item = new MeuItem(1890);

      // When: insert twice and build/normalize the heap
      heap.insere(item);
      heap.insere(item);
      heap.constroi();

      // Then: two removals should succeed and return the same instance
      Item firstRemoved = heap.retiraMax();
      assertSame("First removal should return the inserted instance", item, firstRemoved);

      Item secondRemoved = heap.retiraMax();
      assertSame("Second removal should return the inserted instance (second copy)", item, secondRemoved);

      // After two removals the heap should be empty
      try {
          heap.retiraMax();
          fail("Expected Exception when removing from an empty heap after two pops");
      } catch (Exception e) {
          String msg = e.getMessage();
          if (msg != null) {
              assertTrue("Exception message should reference empty heap", msg.toLowerCase().contains("vazio") || msg.toLowerCase().contains("heap"));
          }
      }
  }

  /**
   * Given an array with some positions populated and others null,
   * When copia is invoked and a max removal is performed,
   * Then the returned item should match the expected populated element.
   */
  @Test(timeout = 4000)
  public void test6()  throws Throwable  {
      // Given
      FPHeapMax heap = new FPHeapMax(2178);
      Item[] items = new Item[4];
      MeuItem shared = new MeuItem(1890);

      // When: insert one element and prepare an array with that element in multiple positions
      heap.insere(shared);
      items[1] = shared;
      heap.insere(shared);
      items[3] = shared;
      heap.copia(items);

      // Then: a removal should return the shared instance
      Item removed = heap.retiraMax();
      assertSame("retiraMax should return the shared inserted instance", shared, removed);

      // And further removal should either return another instance or throw when empty; ensure behavior is consistent
      try {
          heap.retiraMax();
          // either a second removal is allowed or throws; if allowed, it should be same instance (since we inserted same object)
      } catch (Exception e) {
          // acceptable end state
          String msg = e.getMessage();
          if (msg != null) {
              assertTrue("Exception message should reference heap emptiness", msg.toLowerCase().contains("vazio") || msg.toLowerCase().contains("heap"));
          }
      }
  }

  /**
   * Given a heap and an array containing null and non-null positions,
   * When copia is called with this array,
   * Then attempting to retiraMax may result in a NullPointerException depending on internal implementation.
   */
  @Test(timeout = 4000)
  public void test7()  throws Throwable  {
      // Given
      FPHeapMax heap = new FPHeapMax(2698);
      MeuItem a = new MeuItem(0);
      Item[] arr = new Item[8];
      arr[2] = a;
      MeuItem b = new MeuItem(418);
      arr[3] = b;
      arr[7] = a;

      // When
      heap.copia(arr);

      // Then: attempt to remove max — original behavior produced NullPointerException
      try {
          heap.retiraMax();
          fail("Expected NullPointerException when retiraMax is invoked after copying an array with null holes");
      } catch (NullPointerException npe) {
          // Acceptable: message typically null
          assertNotNull("NullPointerException was thrown as expected", npe);
      } catch (Exception e) {
          // If another exception arises, ensure it's at least indicative of invalid state
          String msg = e.getMessage();
          if (msg != null) {
              assertTrue("Unexpected exception message when copying array with nulls: " + msg, msg.toLowerCase().contains("null") || msg.toLowerCase().contains("heap"));
          }
      }
  }

